    >
      <div onClick={(e) => e.stopPropagation()} style={{ width: "100%", maxWidth: 420, borderRadius: 16, background: "var(--surface)", border: "1px solid var(--border)", boxShadow: "0 32px 100px rgba(0,0,0,0.7)", overflow: "hidden" }}>
