                          {freqAlert === "warning" && <AlertTriangle className="w-3 h-3" style={{ color: "var(--amber)" }} />}
                        </span>
                      </td>
                    )}
                    {visibleColumns.includes("clicks") && (
                      <td style={{ ...tdMetric("clicks"), color: "var(--foreground)" }}>{fmtNum(safeInt(ins.clicks))}</td>
