                    {visibleColumns.includes("cost_per_conversation") && (
                      <td style={{ ...tdMetric("cost_per_conversation"), color: "var(--cyan)" }}>
                        {convsCount > 0 ? fmt$(costPerConv) : "$0.00"}
                      </td>
