                    {visibleColumns.includes("optimization_goal") && level === "adsets" && (
                      <td style={{ ...tdMetric("optimization_goal"), fontSize: 9, color: "var(--text-secondary)" }}>
                        {row.optimization_goal?.replace(/_/g, " ") || "—"}
                      </td>
