/* eslint-disable react/jsx-no-comment-textnodes, @typescript-eslint/no-unused-vars, @typescript-eslint/no-explicit-any, react-hooks/static-components */
"use client";

import React, { useState, useCallback, useRef } from "react";
import {
    Search, TrendingUp, MessageCircle, ThumbsUp, ThumbsDown, Minus,
  Hash, Globe, Loader2, ExternalLink, Heart, Share2, BarChart2,
    Sparkles, Users, Clock, ChevronRight, RefreshCw
} from "lucide-react";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
    PieChart, Pie, Cell, Legend
} from "recharts";
import { useLanguage } from "@/components/layout/LanguageContext";

/* ─────────────────────────────────────────────────────────────
   Types
───────────────────────────────────────────────────────────── */
interface SearchResult {
  keyword: string;
  period: string;
  metrics: {
    mentions: number;
    interactions: number;
    reach: number;
    sentimentScore: number;
    positiveCount: number;
    negativeCount: number;
    neutralCount: number;
    uniqueAuthors: number;
  };
  timeseries: { date: string; count: number; positive: number; negative: number; neutral: number }[];
  sentiment: {
    positive: number;
    negative: number;
    neutral: number;
    positiveThemes: string[];
    negativeThemes: string[];
    neutralThemes: string[];
  };
  topics: { text: string; size: number; sentiment: "positive" | "negative" | "neutral" }[];
  posts: {
    id: string;
    platform: "facebook" | "instagram";
    text: string;
    author: string;
    url: string | null;
    publishedAt: string;
