                        <div style={{ fontSize: "11px", color: "var(--text-muted)", marginTop: 1 }}>
                          {line.displayPhoneNumber} <span style={{ color: "var(--text-secondary)" }}>·</span> ID: {line.id}
                        </div>
                      </div>
                    </div>

                    <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                      {line.isLinked ? (
                        <>
                          <button
                            onClick={() => {
